다음 C 프로그램의 출력 결과는?

#include <stdio.h>

void func(int *p, int *q) {
    if (p > q) return;
    printf("%d ", *p + *q);
    func(p + 1, q - 1);
}

int main(void) {
    int a[] = { 3, 1, 4, 1, 5 };
    func(a, a + 4);
    return 0;
}

