다음 C 프로그램의 출력 결과는?

#include <stdio.h>

void rotate(int *a, int n, int k) {
    k %= n;
    while (k--) {
        int first = a[0];
        int i;
        for (i = 0; i < n - 1; i++) {
            a[i] = a[i + 1];
        }
        a[n - 1] = first;
    }
}

int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    rotate(arr, 5, 7);
    int i;
    for (i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
    return 0;
}
